def generate_department_directory(dept_name: str, dir_template: str) -> str:
    """
    Generate a formatted directory for employees in dept_name using dir_template.

    Raises ValueError on attempts to access sensitive fields or on other errors.
    """
    # allowed and forbidden attribute names on employee
    allowed_attrs = {"name", "job_title", "team", "position", "department"}
    forbidden_attrs = {"wage", "contact_info"}

    # Find all occurrences of employee.<identifier> anywhere in the template
    found_attrs = re.findall(r'employee\.([A-Za-z_][A-Za-z0-9_]*)', dir_template)

    # If any forbidden attribute is referenced, raise ValueError
    for attr in found_attrs:
        if attr in forbidden_attrs:
            raise ValueError(f"Access to sensitive field '{attr}' is not allowed.")
        if attr not in allowed_attrs:
            # Disallow any attribute not explicitly in the allowed list
            raise ValueError(f"Access to unknown or disallowed field '{attr}' is not allowed.")

    # Safe wrapper exposing only allowed, non-sensitive attributes (with aliases)
    class SafeEmployeeView:
        def __init__(self, emp: Employee):
