            self.job_title = emp.job_title
            self.team = emp.team
            # aliases for template convenience
            self.position = emp.job_title
            self.department = emp.team
        def __repr__(self):
            return f"SafeEmployeeView({self.name})"

    try:
        formatted_entries = []
        for emp in employees:
            if emp.team == dept_name:
                safe_emp = SafeEmployeeView(emp)
                # Use str.format with the safe employee view
                formatted = dir_template.format(employee=safe_emp)
                formatted_entries.append(formatted)
        return "\n".join(formatted_entries)
    except ValueError:
        # Re-raise ValueError (e.g., from earlier checks) unchanged
        raise
    except Exception as e:
