import ast

def process_code_input(code_input: str):
    """
    Executes a restricted Python code snippet and returns the result of the final expression if any.
    Raises ValueError for disallowed operations found by static analysis.
    """
    # AST-based static whitelist/blacklist checks
    disallowed_names = {
        'open', 'exec', 'eval', 'compile', '__import__', 'input',
        'globals', 'locals', 'vars', 'exit', 'quit',
        'os', 'sys', 'subprocess', 'socket', 'shutil', 'requests',
        'builtins', '__builtins__'
    }
    disallowed_attr_names = {
        'system', 'popen', 'run', 'remove', 'unlink', 'rmdir',
        'kill', 'exec', 'spawn', 'connect', 'accept', 'send', 'recv', 'open', 'sendfile'
    }

    class SafeNodeVisitor(ast.NodeVisitor):
        def _root_name(self, node):
            # Walk down attribute chain to find a base Name, if any
            while isinstance(node, ast.Attribute):
                node = node.value
            if isinstance(node, ast.Name):
                return node.id
            return None

        def generic_visit(self, node):
            # Continue default traversal
            super().generic_visit(node)

        def visit_Import(self, node):
            raise ValueError("Import statements are not allowed")

        def visit_ImportFrom(self, node):
            raise ValueError("Import statements are not allowed")

        def visit_Global(self, node):
            raise ValueError("Global statements are not allowed")

        def visit_Nonlocal(self, node):
            raise ValueError("Nonlocal statements are not allowed")

        def visit_Delete(self, node):
            raise ValueError("Delete statements are not allowed")

        def visit_With(self, node):
            raise ValueError("With statements are not allowed")

        def visit_Call(self, node):
            # Check the called function itself
            func = node.func
            if isinstance(func, ast.Name):
                if func.id in disallowed_names:
                    raise ValueError(f"Use of '{func.id}' is not allowed")
            elif isinstance(func, ast.Attribute):
                root = self._root_name(func)
                if root in disallowed_names:
                    raise ValueError(f"Attribute access on '{root}' is not allowed")
                if func.attr.startswith('__') or func.attr in disallowed_attr_names:
                    raise ValueError(f"Attribute '{func.attr}' is not allowed")
            # Continue checking args/keywords
            self.generic_visit(node)

        def visit_Attribute(self, node):
            # Disallow dunder attribute access and dangerous attribute names
            if node.attr.startswith('__'):
                raise ValueError("Access to dunder attributes is not allowed")
            if node.attr in disallowed_attr_names:
                raise ValueError(f"Attribute '{node.attr}' is not allowed")
            root = self._root_name(node)
            if root in disallowed_names:
                raise ValueError(f"Attribute access on '{root}' is not allowed")
            self.generic_visit(node)

        def visit_Name(self, node):
            # If the code is loading a dangerous name (using it), block it.
            if isinstance(node.ctx, ast.Load) and node.id in disallowed_names:
                raise ValueError(f"Use of '{node.id}' is not allowed")
            # Allow other names (including binding to these names)
            # Continue traversal
            self.generic_visit(node)

        def visit_ClassDef(self, node):
            # Disallow class definitions to keep things simpler / safer
            raise ValueError("Class definitions are not allowed")

    # Parse code to AST
    try:
        tree = ast.parse(code_input, mode='exec')
    except SyntaxError as e:
        # Re-raise as ValueError with a concise message
        raise ValueError(f"Syntax error in code: {e}") from e

    # Run static checks
    visitor = SafeNodeVisitor()
    visitor.visit(tree)

    # If the last statement is an expression, convert it to assign to _result
    if tree.body and isinstance(tree.body[-1], ast.Expr):
        last_expr = tree.body[-1].value
        assign = ast.Assign(
            targets=[ast.Name(id='_result', ctx=ast.Store())],
            value=last_expr
        )
        tree.body[-1] = assign
        ast.fix_missing_locations(tree)

    # Prepare a restricted execution environment
    safe_builtins = {
        'abs': abs, 'all': all, 'any': any, 'bool': bool, 'chr': chr,
        'complex': complex, 'dict': dict, 'float': float, 'int': int,
        'len': len, 'list': list, 'max': max, 'min': min, 'pow': pow,
        'range': range, 'repr': repr, 'round': round, 'str': str, 'sum': sum,
        'print': print, 'enumerate': enumerate, 'zip': zip, 'map': map,
        'filter': filter, 'sorted': sorted, 'reversed': reversed, 'tuple': tuple,
        'set': set
    }

    safe_globals = {'__builtins__': safe_builtins}
    safe_locals = {}

    # Compile and execute
    compiled = compile(tree, filename='<user_code>', mode='exec')
    exec(compiled, safe_globals, safe_locals)

    # Return the result if present
    if '_result' in safe_locals:
        return safe_locals['_result']
    return None
